import importlib.util, inspect, traceback, sys, types, os, tempfile, pathlib

# minimal pytest shim
sys.modules['pytest'] = types.ModuleType('pytest')

spec = importlib.util.spec_from_file_location('test_logagg', sys.argv[1])
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

fns = [(n,f) for n,f in inspect.getmembers(mod, inspect.isfunction)
       if n.startswith('test_')]
passed = failed = 0
for name, fn in fns:
    try:
        sig = inspect.signature(fn)
        if 'tmp_path' in sig.parameters:
            with tempfile.TemporaryDirectory() as td:
                fn(pathlib.Path(td))
        else:
            fn()
        print('PASS', name); passed += 1
    except Exception:
        print('FAIL', name); traceback.print_exc(); failed += 1
print(f'{passed} passed, {failed} failed')
sys.exit(1 if failed else 0)
